gRD(){return"Cash-out"},
gRX(){return"Premio ganado"},
gRY(){return"Beneficio"},
gRS(){return"se usa para calcular el cash-out si falta"},
gRJ(){return"Duraci\xf3n (minutos)"},
gRI(){return"Duraci\xf3n (horas)"},
gRQ(){return'tambi\xe9n acepta "1h 30m", "1:30", etc.'},
gS0(){return"Hora de inicio"},
gRK(){return"Hora de fin"},
gRV(){return"Lugar / Sala"},
gRF(){return"Moneda"},
gRP(){return"CAD, USD, GBP\u2026"},
gRE(){return"Pa\xeds"},
gRO(){return"Canad\xe1, EE. UU., Reino Unido\u2026"},
gRN(){return"Manos por hora"},
gS2(){return"Tama\xf1o de mesa"},
gRU(){return"2\u20139 jugadores"},
gRW(){return"Notas"},
gRZ(){return"Rake / Comisiones"},
gRL(){return"Posici\xf3n final"},
gS3(){return"Total de inscritos"},
gS1(){return"Calidad de mesa (1\u20135)"},
gAS(){return"-- No est\xe1 en el archivo --"},
gS7(){return"Falta la fecha"},
