S5(a){return'Buy-in no v\xe1lido: "'+a+'"'},
gS8(){return"Sin columna de resultado: se registrar\xe1 $0 de beneficio"},
SN(a,b){var s=null
return A.bs(a,s,this.a,s,"1 sesi\xf3n de cash tiene ciegas",""+a+" sesiones de cash tienen ciegas",s,s)+' que no se pueden leer para BB/100 (p. ej. "'+b+'"). Se importar\xe1n igual, pero no contar\xe1n para BB/100.'},
gSg(){return"Ninguna columna de resultado asignada"},
gSf(){return"No has asignado Cash-out, Premio ganado ni Beneficio.\n\nTodas las sesiones importadas mostrar\xe1n $0 de beneficio.\n\n\xbfImportar de todos modos?"},
gS4(){return"Volver"},
gRw(){return"Importar igual"},
